// Reuse the unchanged actual-window harness and its frozen six before cases.
#define main rememberedSettingsBaseMain
#include "RememberedSettingsTests.cpp"
#undef main
#include "ui/AdjustmentAdvancedControls.h"
#include "imaging/wic_codec.h"
#include <QJsonDocument>
